const id=(n:number)=>`00000000-0000-4000-8000-${String(n).padStart(12,'0')}`,at='2026-10-17T00:00:00.000Z',worker=new URLSearchParams(location.search).get('fixtureRole')==='worker',actor=id(worker?2:1);
